            } else {
                consecutivePollingFailures++;
                const lSeen = Math.max(botState.lastTickTime || 0, lastSyncTimestamp || 0);
                if (consecutivePollingFailures >= 20 && (Date.now() - lSeen > 120000)) {
                    botState.account.serverConnected = false;
